package com.companages.service;
import com.companages.dto.MemberDtos.ChartNode; import com.companages.entity.Member; import com.companages.repository.MemberRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class OrganizationChartService { private final MemberRepository members; private final OrganizationAccessService access; public OrganizationChartService(MemberRepository m,OrganizationAccessService a){members=m;access=a;} @Transactional(readOnly=true) public List<ChartNode> chart(Long oid,String search){access.requireMember(oid);List<Member> all=members.findAllByOrganizationIdOrderByName(oid);Set<Long> visible=new HashSet<>();if(search==null||search.isBlank())all.forEach(m->visible.add(m.getId()));else for(Member m:all)if(m.getName().toLowerCase().contains(search.toLowerCase())){Member x=m;while(x!=null){visible.add(x.getId());x=x.getManager();}}Map<Long,List<Member>> children=new HashMap<>();for(Member m:all)if(m.getManager()!=null)children.computeIfAbsent(m.getManager().getId(),k->new ArrayList<>()).add(m);return all.stream().filter(m->m.getManager()==null&&visible.contains(m.getId())).map(m->node(m,children,visible,new HashSet<>())).toList();} private ChartNode node(Member m,Map<Long,List<Member>> children,Set<Long> visible,Set<Long> path){if(!path.add(m.getId()))return leaf(m,List.of());List<ChartNode> nested=children.getOrDefault(m.getId(),List.of()).stream().filter(c->visible.contains(c.getId())).map(c->node(c,children,visible,new HashSet<>(path))).toList();return leaf(m,nested);} private ChartNode leaf(Member m,List<ChartNode> children){return new ChartNode(m.getId(),m.getName(),m.getEmail(),m.getAvatarUrl(),m.getPosition()==null?null:m.getPosition().getName(),m.getTeam()==null?null:m.getTeam().getName(),m.getAccessRole().name(),m.getManager()==null?null:m.getManager().getId(),children);} }
